{"cmd": "python3 -c "
import json, os
results_dir = '/opt/public_eval/results'
for f in sorted(os.listdir(results_dir)):
    if f.endswith('.json'):
        with open(os.path.join(results_dir, f)) as fh:
            d = json.load(fh)
        print(f'=== {f[:20]}... ===')
        if 'aggregate' in d:
            print(f\"  aggregate (raw time): {d['aggregate']}\")
        if 'score' in d:
            print(f\"  score: {d.get('score', 'N/A')}\")
        if 'valid' in d:
            print(f\"  valid: {d['valid']}\")
        # Check per-case
        cases = d.get('cases', {})
        if cases:
            print(f'  num cases: {len(cases)}')
            # print first case details
            first = list(cases.keys())[0]
            print(f'  {first}: {list(cases[first].keys())}')
"
"}
